python3 - <<'EOF'
import re

def parse(path):
    macro = pin = None
    out = []  # (macro, header fields)
    uses = {}  # (macro,pin) -> use
    dirs = {}
    headers = {}
    cur = {}
    for line in open(path):
        s = line.strip()
        if s.startswith('MACRO '):
            macro = s.split()[1]; cur = {'MACRO': macro}
        elif s.startswith('CLASS ') and macro: cur['CLASS'] = s.split()[1]
        elif s.startswith('SIZE ') and macro: cur['SIZE'] = s.split()[1] + ' BY ' + s.split()[3]
        elif s.startswith('SYMMETRY') and macro: cur['SYM'] = ' '.join(s.split()[1:-1])
        elif s.startswith('ORIGIN ') and macro: cur['ORIGIN'] = s.split()[1] + ' ' + s.split()[2]
        elif s.startswith('FOREIGN ') and macro: cur['FOREIGN'] = ' '.join(s.split()[1:])
        elif s.startswith('SITE ') and macro: cur['SITE'] = s.split()[1]
        elif s.startswith('PIN ') and macro:
            pin = s.split()[1]; headers.setdefault(macro, {}).setdefault('pins', []).append(pin)
        elif s == 'END ' + macro if macro else False:
            out.append(cur); cur = {}
        if pin:
            if s.startswith('USE '): uses[(macro,pin)] = s.split()[1]
            if s.startswith('DIRECTION '): dirs[(macro,pin)] = s.split()[1]
    return headers, uses, dirs

h1,u1,d1 = parse('IP/IO/ICsprout_55LLULP1233_IO_251013/lef/ICSIOA_N55_3P3_1P6M1TM.lef')
h2,u2,d2 = parse('IP/IO/ICsprout_55LLULP1233_IO_251013/lef/ICSIOA_N55_3P3_1P6M1TM_ecos.lef')

print("=== MACRO count:", len(h1), len(h2))
for m in h1:
    p = h1[m]
    print(f"{m:<28} CLASS={p.get('CLASS','?'):<8} SIZE={p.get('SIZE','?'):<16} SITE={p.get('SITE','?'):<8} SYM={p.get('SYM','?)}" if False else
          f"{m:<28} CLASS={p.get('CLASS','?'):<8} SIZE={p.get('SIZE','?'):<16} SITE={p.get('SITE','?')}")

print("\n=== USE SIGNAL->GROUND pins:")
for k in u1:
    if k in u2 and u1[k]=='SIGNAL' and u2[k]=='GROUND':
        print(f"  {k[0]:<28} {k[1]}")

print("\n=== DIRECTION changes:")
for k in d1:
    if k in d2 and d1[k]!=d2[k]:
        print(f"  {k[0]:<28} {k[1]}: {d1[k]} -> {d2[k]}")
EOF

